using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CyberPW.Assistant2{
[Flags]internal enum FrameEdges{None=0,Left=1,Top=2,Right=4,Bottom=8,All=15}
internal static class FramePainter{public static void Draw(Graphics g,Control c,FrameEdges edges,Color color,int thickness){if(edges==FrameEdges.None||c.Width<2||c.Height<2)return;using(var p=new Pen(color,thickness)){float h=thickness/2f;if((edges&FrameEdges.Left)!=0)g.DrawLine(p,h,0,h,c.Height);if((edges&FrameEdges.Top)!=0)g.DrawLine(p,0,h,c.Width,h);if((edges&FrameEdges.Right)!=0)g.DrawLine(p,c.Width-h-1,0,c.Width-h-1,c.Height);if((edges&FrameEdges.Bottom)!=0)g.DrawLine(p,0,c.Height-h-1,c.Width,c.Height-h-1);}}}
internal sealed class GradientPanel:Panel{public Color StartColor=Color.FromArgb(2,37,43),EndColor=Color.FromArgb(9,73,57),BorderColor=Theme.Gold;public FrameEdges Edges=FrameEdges.None;public int BorderThickness=3;public GradientPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaintBackground(PaintEventArgs e){if(ClientRectangle.Width<1||ClientRectangle.Height<1)return;using(var b=new LinearGradientBrush(ClientRectangle,StartColor,EndColor,90F))e.Graphics.FillRectangle(b,ClientRectangle);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);FramePainter.Draw(e.Graphics,this,Edges,BorderColor,BorderThickness);}}
internal sealed class FramedFlowPanel:FlowLayoutPanel{public Color BorderColor=Theme.Gold;public int BorderThickness=3;public FrameEdges Edges=FrameEdges.None;public FramedFlowPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);FramePainter.Draw(e.Graphics,this,Edges,BorderColor,BorderThickness);}}
}